from __future__ import annotations

import datetime as dt
import re
from enum import IntEnum, StrEnum, unique
from typing import Any, Final, NamedTuple

from catholic_mass_readings import USCCB

from stjoseph.api import constants, utils

# Matches titles generated by generators.generate_title, e.g. "Mass October 10, 2026 - 5:30 PM: ..."
_TITLE_DATE_RE: Final[re.Pattern[str]] = re.compile(
    r"^Mass (?P<date>[A-Z][a-z]+ \d{1,2}, \d{4})(?: - (?P<time>\d{1,2}:\d{2}) ?(?P<ampm>[AaPp][Mm]))?"
)


class LiveStream(NamedTuple):
    id: str
    title: str
    description: str
    published_at: dt.datetime | None
    scheduled_start: dt.datetime | None
    actual_start: dt.datetime | None
    actual_end: dt.datetime | None

    def __repr__(self) -> str:
        description = utils.truncate(self.description)
        result = f"id='{self.id}' title='{self.title}' description='{description}' scheduled='{self.scheduled_start}'"
        if self.published_at:
            result += f", published_at='{self.published_at}"

        if self.actual_start and self.actual_end:
            result += f", actual_start='{self.actual_start}, actual_end='{self.actual_end}, duration='{self.duration}'"
        return result

    def __str__(self) -> str:
        return repr(self)

    @property
    def duration(self) -> dt.timedelta | None:
        """Gets the actual duration of the mass"""
        return self.actual_end - self.actual_start if self.actual_start and self.actual_end else None

    def is_eligible_for_deletion(self) -> bool:
        if self.scheduled_start and self.scheduled_start.date() >= USCCB.today():
            return False  # starting in the future.

        return (
            not self.published_at
            or self.duration is None
            or self.duration.total_seconds() < dt.timedelta(minutes=15).total_seconds()
        )

    def is_stale(self, tz: dt.tzinfo = constants.DEFAULT_TIMEZONE) -> bool:
        """Determines if the stream was scheduled for a past date but never went live."""
        return (
            self.actual_start is None
            and self.scheduled_start is not None
            and self.scheduled_start.astimezone(tz).date() < USCCB.today()
        )

    def get_title_start(self) -> dt.datetime | None:
        """Gets the (naive) date/time of the mass parsed from the title, or None if the title isn't recognized."""
        match = _TITLE_DATE_RE.match(self.title)
        if match is None:
            return None
        try:
            date = dt.datetime.strptime(match["date"], "%B %d, %Y")  # noqa: DTZ007
            if match["time"] is None:
                return date
            time = dt.datetime.strptime(f"{match['time']} {match['ampm']}", "%I:%M %p")  # noqa: DTZ007
        except ValueError:
            return None  # e.g. a typo in the month name.
        return date.replace(hour=time.hour, minute=time.minute)

    def get_aired_start(self, tz: dt.tzinfo = constants.DEFAULT_TIMEZONE) -> dt.datetime | None:
        """
        Gets the mass time (from the title, else the schedule) on the date the stream actually went live.
        Returns None if the stream never went live or went live on the date it is labeled with.
        """
        if self.actual_start is None:
            return None
        labeled = self.get_title_start()
        if labeled is None or labeled.time() == dt.time():
            if self.scheduled_start is None:
                return None
            scheduled = self.scheduled_start.astimezone(tz)
            labeled = (labeled or scheduled).replace(hour=scheduled.hour, minute=scheduled.minute)
        actual = self.actual_start.astimezone(tz)
        if labeled.date() == actual.date():
            return None
        return actual.replace(hour=labeled.hour, minute=labeled.minute, second=0, microsecond=0)


@unique
class Weekday(IntEnum):
    MONDAY = 0
    TUESDAY = 1
    WEDNESDAY = 2
    THURSDAY = 3
    FRIDAY = 4
    SATURDAY = 5
    SUNDAY = 6


@unique
class BroadcastStatus(StrEnum):
    ACTIVE = "active"
    ALL = "all"
    COMPLETED = "completed"
    UPCOMING = "upcoming"


@unique
class BroadcastType(StrEnum):
    ALL = "all"
    EVENT = "event"
    PERSISTENT = "persistent"


