class RecordingLocation(NamedTuple):
    description: str
    latitude: float
    longitude: float
    altitude: int = 0

    def to_recording_details(self) -> dict[str, Any]:
        """Converts to the YouTube Data API ``recordingDetails`` representation."""
        return {
            "locationDescription": self.description,
            "location": {"latitude": self.latitude, "longitude": self.longitude, "altitude": self.altitude},
        }


DEFAULT_LOCATION: Final[RecordingLocation] = RecordingLocation(
    description=constants.YOUTUBE_RECORDING_LOCATION_DESCRIPTION, latitude=40.9270067, longitude=-74.3023004
)
